 PayloadCore97 poses=fresh();String pa=join(poses,"pilot-a");act(poses,pa,"claim","front","");PayloadCore97.Tx pt=send(poses,pa,"front","gimbal",-30,10);poses.receive(v.get("gimbalWrongDevice"),++now);ok("wrong device pose cannot populate selected",!Boolean.TRUE.equals(payload(poses,"front").get("poseFresh")));poses.receive(v.get("gimbal"),++now);ok("pose independent and correct units",Math.abs(((Number)payload(poses,"front").get("pitchDeg")).doubleValue()+30)<.001&&pt.state.equals("SENT_UNATTRIBUTED"));long poseAt=((Number)payload(poses,"front").get("poseAtMs")).longValue();now+=200;poses.receive(v.get("gimbalDuplicate"),now);ok("duplicate boot pose cannot refresh age",((Number)payload(poses,"front").get("poseAtMs")).longValue()==poseAt);poses.receive(v.get("gimbalContradictory"),++now);ok("contradictory boot pose unknown",!Boolean.TRUE.equals(payload(poses,"front").get("poseFresh"))&&payload(poses,"front").get("poseUncertainty").equals("CONTRADICTORY_POSE_SAME_BOOT_MS"));poses.receive(v.get("managerNoAuthority"),++now);no("primary authority lost blocks setpoint",()->prepare(poses,pa,"front","gimbal",-20,10));
 PayloadCore97 authority=fresh();String au=join(authority,"pilot-a");act(authority,au,"claim","front","");act(authority,au,"claim","center","");send(authority,au,"front","authority",0,0);now+=100;no("authority shared ACK key remains fenced",()->send(authority,au,"center","authority",0,0));
