 PayloadCore97 quota=fresh();String qa=join(quota,"pilot-a");act(quota,qa,"claim","front","");for(int i=0;i<PayloadCore97.INTENT_LIMIT;i++){long next=1100+i*101;if(i%10==0){now=next;quota.receive(v.get("pulse"+(i/10)),now);quota.heartbeat(qa,now);}now=next;send(quota,qa,"front","gimbal",-20,0);}now+=101;no("intent quota refuses before next wire",()->prepare(quota,qa,"front","gimbal",-20,0));ok("quota retains all original intents",((List<?>)snap(quota).get("transactions")).size()==PayloadCore97.INTENT_LIMIT);ok("maximum snapshot bounded below native record limit",json(snap(quota)).getBytes("UTF-8").length<100000);
